def convert(numbers, imag=None):
    if imag is not None:
        z = complex(numbers, imag)
    elif isinstance(numbers, (list, tuple)):
        if len(numbers) == 2:
            z = complex(numbers[0], numbers[1])
        else:
            z = complex(numbers[0])
    else:
        z = complex(numbers)
    return cmath.polar(z)

def prime_num(n):
    if not isinstance(n, int) or n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

